// DASHBOARD variant of WF-01 (read-only). Separate path so OpenClaw's WF-01 is untouched.
// The dashboard always sends an explicit window; no defaults are guessed here.
const first = $input.first().json;
const body = first.body || first;
const request_id = (typeof body.request_id === 'string') ? body.request_id : undefined;
const MAX_WINDOW_DAYS = 45;   // month view + padding
const bad = (message) => [{ json: { valid: false, code: 'VALIDATION_ERROR', message, request_id } }];
const iso = (v) => typeof v === 'string' && v.trim() !== '' && !isNaN(new Date(v).getTime());

const { timeMin, timeMax } = body;
if (!iso(timeMin)) return bad('timeMin is required and must be ISO 8601');
if (!iso(timeMax)) return bad('timeMax is required and must be ISO 8601');
const span = new Date(timeMax).getTime() - new Date(timeMin).getTime();
if (span <= 0) return bad('timeMax must be after timeMin');
if (span > MAX_WINDOW_DAYS * 86400000) return bad('window must be ' + MAX_WINDOW_DAYS + ' days or less');

let maxResults = parseInt(body.maxResults ?? 250, 10);
if (isNaN(maxResults)) return bad('maxResults must be a number');
maxResults = Math.max(1, Math.min(500, maxResults));

return [{ json: { valid: true, timeMin, timeMax, maxResults, request_id, _startTime: Date.now() } }];

const pick = (t) => (t && (t.dateTime || t.date)) || null;
function mapEvent(e) {
  const video = (e.conferenceData && Array.isArray(e.conferenceData.entryPoints)) ? e.conferenceData.entryPoints.find((p) => p.entryPointType === 'video') : undefined;
  const priv = (e.extendedProperties && e.extendedProperties.private) || {};
  return {
    id: e.id, title: e.summary || '(no title)', start: pick(e.start), end: pick(e.end),
    allDay: !!(e.start && e.start.date && !e.start.dateTime), timeZone: (e.start && e.start.timeZone) || null,
    location: e.location || null, meet_link: e.hangoutLink || (video && video.uri) || null, htmlLink: e.htmlLink || null,
    attendees_count: Array.isArray(e.attendees) ? e.attendees.length : 0, transparency: e.transparency || 'opaque',
    eventType: e.eventType || 'default', recurringEventId: e.recurringEventId || null, updated: e.updated || null,
    protectedByEa: priv.jstackProtected === 'true', calendarId: 'primary'
  };
}

// Structured output for the dashboard: stable ids, full titles, all-day flag, Google link,
// protectedByEa (blocks made by calendar-edit's "block"). No prose, no size cap.
const validated = $('Validate Input').first().json;
const events = $input.all().map((i) => i.json).filter((e) => e && e.id && e.status !== 'cancelled').map(mapEvent);
return [{ json: {
  ok: true, request_id: validated.request_id,
  duration_ms: Date.now() - (validated._startTime || Date.now()),
  data: { count: events.length, window: { timeMin: validated.timeMin, timeMax: validated.timeMax }, events }
} }];
